  "evaluations": [
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BGD:17068",
      "iso3": "BGD",
      "ruler_id": "2992",
      "ruler_year_id": 17068,
      "ruler_name": "Sheikh Hasina",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "6B",
      "rubric_version": "chapter_6b_v3",
      "calibration_batch_id": "chapter-judge:2022-saturation-v3-stage1-controlled:2022:6B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:ETH:16782",
        "dossier:2022-top20-hybrid-v2:2022:COD:16113",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810"
      ],
      "score_1_to_10": 5.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.74,
      "plausible_score_range": {
        "lower": 4.0,
        "upper": 6.0
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0088",
          "explanation": "World Bank says extreme poverty fell to 5.0 percent in 2022 and other wellbeing indicators improved over time."
        },
        {
          "evidence_id": "E0077",
          "explanation": "ROSC II shows concrete education delivery results, including trained teachers, retention, and pass-rate gains."
        },
        {
          "evidence_id": "E0086",
          "explanation": "UNICEF reports a real 2022 flood-response effort with major emergency supplies and state-linked coordination."
        },
        {
          "evidence_id": "E0089",
          "explanation": "IMF summary indicates significant social-protection spending and expanded cash-transfer channels in FY22."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0079",
          "explanation": "Child-budget share stayed stagnant and UNICEF flagged low utilization and rushed year-end spending."
        },
        {
          "evidence_id": "E0083",
          "explanation": "Schools still lacked basic water, sanitation, and hygiene services at substantial rates in 2022."
        },
        {
          "evidence_id": "E0087",
          "explanation": "WFP notes persistent malnutrition, gender inequality, and the need for shock-responsive protection."
        }
      ],
      "inherited_baseline_and_constraints": "Bangladesh started with real administrative capacity in disaster response and social programs, but climate shocks, incomplete WASH, undernutrition, and thin execution audits constrained what could be credited to the ruler.",
      "ruler_attribution": "Mostly institutional and state-level rather than personal; the best evidence shows Hasina-era welfare choices and response capacity, not a clean personal implementation trail.",
      "supported_lenses": [
        "6B.2 access and protection",
        "6B.3 vulnerable groups",
        "6B.6 crisis response",
        "6B.8 dignity and equality",
        "6B.10 life chances"
      ],
      "missing_or_weak_lenses": [
        "6B.1 welfare as core purpose",
        "6B.4 professional administration",
        "6B.5 measurement and correction",
        "6B.7 anti-patronage use of benefits",
        "6B.9 durability"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0079",
          "explanation": "Implementation problems and low budget utilization limit how much credit the state can take."
        },
        {
          "evidence_id": "E0083",
          "explanation": "Basic school WASH remained incomplete, which weakens the broad welfare story."
        },
        {
          "evidence_id": "E0087",
          "explanation": "Structural malnutrition and inequality remained visible in the welfare baseline."
        }
      ],
      "source_mix": "Mostly World Bank, UNICEF, WFP, IMF, and one domestic budget speech; strong official coverage, but attribution is often to government systems rather than Hasina personally.",
      "structured_prior_summary": "Structured local priors were not collected in this experiment; the judgment relies on the embedded cited dossier alone.",
      "chapter_rationale": "Bangladesh shows a real but uneven welfare record in 2022. The dossier supports credit for poverty reduction, education delivery, targeted social protection, climate resilience, and flood response, but it also shows stagnant child-budget execution, major WASH gaps, and persistent malnutrition. The stronger evidence is mostly institutional rather than personal, so the chapter belongs in the middle band rather than the high end.",
      "lower_anchor_rejected": "A score below 5 would ignore the dossier's concrete poverty, education, protection, and emergency-response gains.",
      "higher_anchor_rejected": "A score above 5 would overread mixed program evidence as broad, durable, and independently verified improvement.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "evidenced_service_domains",
          "value": "education, child protection, social protection, flood relief, WASH"
        },
        {
          "field": "distribution_and_dignity",
          "value": "Targeting of poor households and vulnerable children is visible, but sanitation and utilization gaps remain."
        },
        {
          "field": "crisis_context",
          "value": "Flood response and climate resilience materially matter to the welfare score."
        },
        {
          "field": "institutional_durability",
          "value": "The dossier shows functioning systems, but not enough independent evidence of durable correction and follow-through."
        },
        {
          "field": "trajectory",
          "value": "Improving from a difficult baseline, but still mixed rather than transformative."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
      "iso3": "BRA",
      "ruler_id": "3413",
      "ruler_year_id": 19646,
      "ruler_name": "Jair Bolsonaro",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "6B",
      "rubric_version": "chapter_6b_v3",
      "calibration_batch_id": "chapter-judge:2022-saturation-v3-stage1-controlled:2022:6B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:ETH:16782",
        "dossier:2022-top20-hybrid-v2:2022:COD:16113",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810"
      ],
      "score_1_to_10": 5.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.72,
      "plausible_score_range": {
        "lower": 4.0,
        "upper": 6.0
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0071",
          "explanation": "The Auxilio Brasil decree assigns ministries responsibility for conditionality tracking and social assistance coordination."
        },
        {
          "evidence_id": "E0074",
          "explanation": "Bolsonaro signed Internet Brasil, creating a concrete school-connectivity program for public-school students."
        },
        {
          "evidence_id": "E0078",
          "explanation": "Late-2022 vaccine incorporation shows a direct health-policy act for young children."
        },
        {
          "evidence_id": "E0080",
          "explanation": "Casa Verde e Amarela housing support was expanded with higher financing limits for households."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0068",
          "explanation": "UNICEF says millions of children were out of school, with child labor and learning problems still present."
        },
        {
          "evidence_id": "E0069",
          "explanation": "The World Bank estimated severe food insecurity and high poverty, with only partial cushioning from transfers."
        },
        {
          "evidence_id": "E0072",
          "explanation": "Monitoring problems in Auxilio Brasil show implementation weakness rather than clean delivery."
        }
      ],
      "inherited_baseline_and_constraints": "Brazil inherited pandemic damage, inflation pressure, and major inequality; Bolsonaro's welfare record is therefore a mix of direct policy, electoral spending, and macro distress.",
      "ruler_attribution": "Moderate: the dossier shows clear presidential and ministerial action, but much of the impact is mediated, partial, or election-year relief.",
      "supported_lenses": [
        "6B.2 access and relief",
        "6B.3 vulnerable groups",
        "6B.4 program administration",
        "6B.6 crisis response",
        "6B.9 institutional rollout"
      ],
      "missing_or_weak_lenses": [
        "6B.1 welfare as core purpose",
        "6B.5 measurement and correction",
        "6B.7 anti-patronage use of benefits",
        "6B.8 dignity and equity",
        "6B.10 life chances"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0068",
          "explanation": "Mass school nonattendance shows serious harm remained in the child-welfare domain."
        },
        {
          "evidence_id": "E0069",
          "explanation": "Food insecurity and poverty stayed high despite some transfer cushioning."
        }
      ],
      "source_mix": "Official decrees, ministry notices, UNICEF, World Bank, and Reuters reporting; the record is strong on policy action but weaker on independent outcome audits.",
      "structured_prior_summary": "Structured local priors were not collected in this experiment; the judgment rests on the cited dossier.",
      "chapter_rationale": "Brazil in 2022 shows real welfare activity but not a broad, durable social upgrade. Bolsonaro's government expanded housing, school connectivity, health, and cash-transfer mechanisms, yet the same record shows high food insecurity, major school absence, and implementation problems. That keeps the score in the middle band: real action, but mixed results and limited evidence of durable life-chance gains.",
      "lower_anchor_rejected": "A score below 5 would discount the dossier's clear cash-transfer, housing, health, and connectivity actions.",
      "higher_anchor_rejected": "A score above 5 would treat policy announcements and partial delivery as stronger evidence of impact than the record supports.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "evidenced_service_domains",
          "value": "health, education, housing, school connectivity, social assistance"
        },
        {
          "field": "distribution_and_dignity",
          "value": "Evidence reaches vulnerable groups, but the national distribution picture remains uneven."
        },
        {
          "field": "crisis_context",
          "value": "Inflation and pandemic-era learning disruption shape the welfare baseline."
        },
        {
          "field": "institutional_durability",
          "value": "Administrative rules exist, but outcome verification and durability are weak."
        },
        {
          "field": "trajectory",
          "value": "Targeted welfare policy expanded, but the overall social trajectory remains mixed."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:CHN:15832",
      "iso3": "CHN",
