        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810"
      ],
      "score_1_to_10": 7.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.79,
      "plausible_score_range": {
        "lower": 6.5,
        "upper": 7.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0084",
          "explanation": "The poverty-relapse monitoring mechanism and expanded follow-up support show active institutional protection."
        },
        {
          "evidence_id": "E0088",
          "explanation": "China created 12.06 million urban jobs in 2022, a large labor-market contribution."
        },
        {
          "evidence_id": "E0083",
          "explanation": "Incomes of people lifted out of poverty grew 14.3 percent in 2022, above rural income growth."
        },
        {
          "evidence_id": "E0078",
          "explanation": "The basic public-health package covered multiple vulnerable-group services and instructed local access."
        },
        {
          "evidence_id": "E0081",
          "explanation": "Subsidized-rental and old-community renovation targets indicate large housing effort."
        },
        {
          "evidence_id": "E0085",
          "explanation": "Official income and consumption data show positive income growth in 2022."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0087",
          "explanation": "The property downturn was severe and undercut an easy welfare read."
        },
        {
          "evidence_id": "E0088",
          "explanation": "Youth unemployment remained high, pointing to major distributional strain."
        },
        {
          "evidence_id": "E0085",
          "explanation": "Household consumption fell, which tempers the score despite income gains."
        }
      ],
      "inherited_baseline_and_constraints": "China entered 2022 with strong state capacity and high baseline human capital, but also with property-sector stress, COVID disruption, and uneven local execution that limit how much can be credited to Xi personally.",
      "ruler_attribution": "Strong at the system level and moderate personally: Xi set the political line, while implementation was collective and decentralized.",
      "supported_lenses": [
        "6B.2 access and protection",
        "6B.3 vulnerable groups",
        "6B.4 service financing",
        "6B.5 monitoring and correction",
        "6B.9 durable institutions",
        "6B.10 life chances"
      ],
      "missing_or_weak_lenses": [
        "6B.1 welfare as core purpose",
        "6B.6 crisis suffering reduction",
        "6B.7 anti-patronage risk",
        "6B.8 dignity and equal opportunity"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0087",
          "explanation": "Housing-sector stress and declining investment are serious welfare offsets."
        },
        {
          "evidence_id": "E0088",
          "explanation": "Youth unemployment remains a visible disadvantage even in a strong jobs year."
        },
        {
          "evidence_id": "E0085",
          "explanation": "Consumption weakness makes the welfare gain less complete than income data alone suggest."
        }
      ],
      "source_mix": "Mostly official Chinese state statistics and ministry releases, with the welfare picture cross-checked by multilateral summaries; attribution is mainly institutional rather than personal.",
      "structured_prior_summary": "Structured local priors were not collected in this experiment; the dossier's own cited evidence is sufficient for scoring.",
      "chapter_rationale": "China's 2022 social-well-being record is strong in breadth and state capacity. The dossier supports large-scale job creation, poverty-consolidation mechanisms, health coverage, housing investment, and income growth, even though property stress, youth unemployment, and weaker consumption limit the score. This is above the middle because the gains are broad and institutional, but below the top tier because equity, durability, and personal attribution are still imperfect.",
      "lower_anchor_rejected": "A lower score would ignore the scale of documented jobs, poverty-consolidation, health, and housing measures.",
      "higher_anchor_rejected": "A higher score would overstate uniformity, durability, and personal attribution despite property and labor-market weakness.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "evidenced_service_domains",
          "value": "jobs, poverty consolidation, housing, health, income support"
        },
        {
          "field": "distribution_and_dignity",
          "value": "Support for rural residents and previously poor households is visible, but distributional gaps remain."
        },
        {
          "field": "crisis_context",
          "value": "COVID, property stress, and youth unemployment are important counterweights."
        },
        {
          "field": "institutional_durability",
          "value": "The monitoring and support mechanism suggests durable state capacity, though local execution remains opaque."
        },
        {
          "field": "trajectory",
          "value": "High-capacity welfare expansion with meaningful but incomplete gains."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:COD:16113",
      "iso3": "COD",
      "ruler_id": "2830",
