      "ruler_name": "Félix Tshisekedi",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "6B",
      "rubric_version": "chapter_6b_v3",
      "calibration_batch_id": "chapter-judge:2022-saturation-v3-stage1-controlled:2022:6B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:ETH:16782",
        "dossier:2022-top20-hybrid-v2:2022:COD:16113",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810"
      ],
      "score_1_to_10": 3.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.81,
      "plausible_score_range": {
        "lower": 3.0,
        "upper": 4.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0076",
          "explanation": "The 145-territories program was framed as a major rural development and infrastructure push."
        },
        {
          "evidence_id": "E0084",
          "explanation": "The World Bank approved major governance, transport, and digital connectivity financing."
        },
        {
          "evidence_id": "E0088",
          "explanation": "WHO reports mass vaccination response to cholera, meningitis, and measles outbreaks."
        },
        {
          "evidence_id": "E0090",
          "explanation": "WHO and local teams improved vaccine-data triangulation and program planning."
        },
        {
          "evidence_id": "E0094",
          "explanation": "UNICEF documents emergency WASH, nutrition, and education support for displaced families."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0086",
          "explanation": "World Bank says poverty reduction remained elusive and growth benefits were not broadly shared."
        },
        {
          "evidence_id": "E0095",
          "explanation": "More than 2,000 schools closed amid insecurity and displacement, with only limited temporary learning-space mitigation."
        },
        {
          "evidence_id": "E0088",
          "explanation": "The disease burden itself remained severe, limiting the welfare credit from the response."
        }
      ],
      "inherited_baseline_and_constraints": "The DRC inherited conflict, weak provincial capacity, and severe service fragility; donor-led projects and emergency relief matter, but they cannot be treated as a full domestic welfare transformation.",
      "ruler_attribution": "Mostly indirect and institutional. Tshisekedi can be credited for agenda-setting and government coordination, but the strongest delivery evidence is donor- and partner-mediated.",
      "supported_lenses": [
        "6B.2 access and services",
        "6B.3 vulnerable groups",
        "6B.6 crisis relief",
        "6B.9 institution-building",
        "6B.10 life chances"
      ],
      "missing_or_weak_lenses": [
        "6B.1 welfare as core purpose",
        "6B.4 professional administration",
        "6B.5 measurement and correction",
        "6B.7 anti-patronage",
        "6B.8 dignity and equality"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0086",
          "explanation": "The country update explicitly says growth gains were not broadly shared."
        },
        {
          "evidence_id": "E0095",
          "explanation": "School closures and displacement still dominated child welfare conditions."
        }
      ],
      "source_mix": "World Bank, WHO, UNICEF, and presidential/government statements; the strongest evidence is emergency and donor-assisted rather than fully domestic.",
      "structured_prior_summary": "Structured local priors were not collected in this experiment; the score is anchored in the cited evidence and the dossier's own gap notes.",
      "chapter_rationale": "The DRC's 2022 welfare record is dominated by crisis management rather than broad human-development gains. The dossier shows real activity in road, connectivity, vaccination, and emergency relief, but the same record shows persistent poverty, school closures, displacement, and severe insecurity. That is enough for some credit, but not enough to move beyond the low band.",
      "lower_anchor_rejected": "A score below 3.5 would ignore the existence of real programs, financing, and emergency delivery.",
      "higher_anchor_rejected": "A score above 3.5 would overstate how much those programs overcame conflict-driven deprivation and weak state capacity.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "evidenced_service_domains",
          "value": "roads, digital connectivity, vaccination, WASH, schooling"
        },
        {
          "field": "distribution_and_dignity",
          "value": "The record reaches displaced families and children, but broad access and dignity remain badly constrained."
        },
        {
          "field": "crisis_context",
          "value": "Conflict, displacement, and outbreaks are central to the scoring context."
        },
        {
          "field": "institutional_durability",
          "value": "Delivery depends heavily on partners; durable domestic capacity remains thin."
        },
        {
          "field": "trajectory",
          "value": "Some protective action exists, but the overall trajectory remains weak and fragile."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
      "iso3": "DEU",
      "ruler_id": "2975",
      "ruler_year_id": 16984,
      "ruler_name": "Olaf Scholz",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "6B",
      "rubric_version": "chapter_6b_v3",
      "calibration_batch_id": "chapter-judge:2022-saturation-v3-stage1-controlled:2022:6B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:ETH:16782",
        "dossier:2022-top20-hybrid-v2:2022:COD:16113",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810"
      ],
      "score_1_to_10": 6.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.78,
      "plausible_score_range": {
        "lower": 6.0,
        "upper": 7.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0061",
          "explanation": "Scholz committed to refugee welfare, including accommodation, medical care, schooling, and a safe future."
        },
        {
          "evidence_id": "E0064",
          "explanation": "The statutory minimum wage rose to 12 euros, a clear household-income gain for millions."
        },
        {
          "evidence_id": "E0065",
          "explanation": "Wohngeld Plus and the heating subsidy were approved for millions of people."
        },
        {
          "evidence_id": "E0066",
          "explanation": "Basic-security benefits were extended to Ukrainian refugees with access to integration, labor, childcare, and health services."
        },
        {
          "evidence_id": "E0101",
          "explanation": "The 200 billion euro energy shield and gas/heat price brake show large-scale crisis protection."
        },
        {
          "evidence_id": "E0102",
          "explanation": "Bürgergeld enacted a major social-security reform at the end of 2022."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0070",
          "explanation": "OECD says the relief packages were not well targeted to vulnerable households and exposed firms."
        },
        {
          "evidence_id": "E0072",
          "explanation": "Employment was strong, but real wages and purchasing power were under pressure."
        },
        {
          "evidence_id": "E0104",
          "explanation": "Many refugee-care functions sat with Länder and municipalities, limiting direct federal delivery credit."
        }
      ],
      "inherited_baseline_and_constraints": "Germany started from a high welfare baseline, but 2022 brought the energy crisis, refugee inflows, and inflation. The score therefore reflects crisis cushioning and social reform rather than transformative social uplift.",
      "ruler_attribution": "Strong cabinet-level attribution under Scholz, though much of the execution was shared with Länder, municipalities, and agencies.",
      "supported_lenses": [
        "6B.2 access and protection",
        "6B.3 vulnerable groups",
        "6B.6 crisis response",
        "6B.9 durable institutions",
        "6B.10 life chances"
      ],
      "missing_or_weak_lenses": [
        "6B.1 welfare as core purpose",
        "6B.4 professional administration",
        "6B.5 measurement and correction",
        "6B.7 anti-patronage",
        "6B.8 dignity and equality"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0070",
          "explanation": "The OECD explicitly criticizes targeting quality, which reduces the upper bound."
        },
        {
          "evidence_id": "E0104",
          "explanation": "Responsibility is shared, so personal chancellorial attribution is partial."
        }
      ],
      "source_mix": "Official federal law and ministry material plus OECD and statistical releases; the record is strong and mostly institutional, with clear policy design and some outcome support.",
      "structured_prior_summary": "Structured local priors were not collected in this experiment; the dossier's own evidence is sufficient for score calibration.",
